    {
      "category": "learning_objective",
      "rationale": "Combine stable pairwise softplus ranking loss with pointwise logistic supervision weighted by 0.2 to constrain score drift. Preserve existing samples, nonpadding averaging, GRU architecture, inference, optimizer, and training limits.",
      "edits": [
        {
          "find": "def bpr_sequence_loss(model: nn.Module, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor) -> torch.Tensor:\n    pos_scores, neg_scores = model(seq, pos, neg)\n    mask = (pos != 0).float()\n    loss = -torch.log(torch.sigmoid(pos_scores - neg_scores) + 1e-8)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "def bpr_sequence_loss(model: nn.Module, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor) -> torch.Tensor:\n    pos_scores, neg_scores = model(seq, pos, neg)\n    mask = (pos != 0).float()\n    pairwise_loss = torch.nn.functional.softplus(neg_scores - pos_scores)\n    pointwise_loss = (\n        torch.nn.functional.softplus(-pos_scores)\n        + torch.nn.functional.softplus(neg_scores)\n    )\n    loss = pairwise_loss + 0.2 * pointwise_loss\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Replace BPR with softplus ranking loss plus 0.2-weighted pointwise logistic loss across all four category models. Checkpoint shapes and predictor remain unchanged."
